import fs from 'node:fs/promises';
import path from 'node:path';
import sharp from 'sharp';
import catalog from '../lib/travel-artwork.json' with { type: 'json' };

// Format/size preparation only; the artwork and palette are generated by imagegen.
const manifestPath = process.argv[2];
if (!manifestPath) throw new Error('Pass the local imagegen source manifest JSON path.');
const sources = JSON.parse(await fs.readFile(manifestPath, 'utf8'));
const root = path.resolve('public/illustrations');
const archive = path.resolve('artifacts/illustration-generation/masters');
const results = [];
for (const item of sources) {
  if (!/^(?:0[1-9]|1[0-2])-[a-z-]+$/.test(item.asset) || !['light', 'dark'].includes(item.theme)) {
    throw new Error('Invalid illustration asset name or theme.');
  }
  const entry = catalog[item.asset];
  if (!entry) throw new Error('Missing artwork filename/alt metadata.');
  const filename = `${entry.filename}-${item.theme}`;
  const destination = path.join(root, item.theme, filename + '.webp');
  const master = path.join(archive, item.theme, filename + '.png');
  await fs.mkdir(path.dirname(destination), { recursive: true });
  await fs.mkdir(path.dirname(master), { recursive: true });
  await fs.copyFile(item.path, master);
  const original = await sharp(item.path).metadata();
  const output = await sharp(item.path).webp({ quality: 90, effort: 6 }).toFile(destination);
  if (output.width !== original.width || output.height !== original.height) throw new Error('Artwork dimensions changed.');
  results.push({ asset: item.asset, theme: item.theme, alt: entry.alt, url: `/illustrations/${item.theme}/${filename}.webp`, width: output.width, height: output.height, sourceBytes: (await fs.stat(item.path)).size, bytes: output.size });
}
await fs.mkdir('artifacts/illustration-generation', { recursive: true });
await fs.writeFile('artifacts/illustration-generation/asset-report.json', JSON.stringify(results, null, 2));
console.log(JSON.stringify({ assets: results.length, sourceBytes: results.reduce((total, item) => total + item.sourceBytes, 0), webBytes: results.reduce((total, item) => total + item.bytes, 0) }, null, 2));
